import { useState, type ReactNode } from 'react'

import { useAtom } from 'jotai'

import ArrowDropDownIcon from '@mui/icons-material/ArrowDropDown'
import FolderOpenIcon from '@mui/icons-material/FolderOpen'
import {
  Box,
  Typography,
  TextField,
  Button,
  FormControl,
  FormLabel,
  RadioGroup,
  FormControlLabel,
  Radio,
  ToggleButton,
  ToggleButtonGroup,
  Paper,
  Stack,
  Alert,
  IconButton,
  InputAdornment,
  ListItemText,
  Menu,
  MenuItem,
} from '@mui/material'

import { fmPlanNameKindAtom } from '@/atoms/planNameKind'
import NumberSpinner from '@/components/NumberSpinner'
import type { ScheduleType, WeekDay } from '@/types/database'
import { toLocalDateKey } from '@/utils/date'
import {
  ALL_WEEKDAYS,
  getWeekDayLabel,
  calculateTotalSessions,
  calculateEndDate,
  formatYearDate,
} from '@/utils/schedule'
import {
  FM_PLAN_NAME_KINDS,
  getFmPlanName,
  parseFmUrl,
  type FmPlanNameKind,
} from '@/utils/unit-utils'

import { FlashManFolderDialog, type FlashManFolderResult } from './FlashManFolderDialog'

export interface PlanFormData {
  name: string
  unitName: string
  unitAmount: number
  totalAmount: number
  scheduleType: ScheduleType
  scheduleDays: WeekDay[]
  startDate: string
}

interface PlanFormProps {
  initialData?: Partial<PlanFormData>
  onSubmit: (data: PlanFormData) => Promise<void>
  onCancel: () => void
  loading: boolean
  error: ReactNode | null
  submitLabel: string
  loadingLabel: string
  title: string
}

export function PlanForm({
  initialData,
  onSubmit,
  onCancel,
  loading,
  error,
  submitLabel,
  loadingLabel,
  title,
}: PlanFormProps) {
  const [fmDialogOpen, setFmDialogOpen] = useState(false)
  // 계획 이름 자동 채움 형식. 마지막으로 고른 값이 localStorage 에 남는다.
  const [nameKind, setNameKind] = useAtom(fmPlanNameKindAtom)
  const [nameKindAnchor, setNameKindAnchor] = useState<HTMLElement | null>(null)

  /** 훈련 단위를 바꾸면서, fm:// 이면 현재 형식으로 계획 이름도 채운다. */
  function withUnitName(prev: PlanFormData, unitName: string): PlanFormData {
    return { ...prev, unitName, name: getFmPlanName(unitName, nameKind) ?? prev.name }
  }

  function handleFmSelect(result: FlashManFolderResult) {
    const unitName = `fm://${result.owner}/${result.repo}${result.path ? '/' + result.path : ''}`
    setFormData((prev) => ({ ...withUnitName(prev, unitName), totalAmount: result.fileCount }))
    setFmDialogOpen(false)
  }

  function handleNameKindSelect(kind: FmPlanNameKind) {
    setNameKind(kind)
    setFormData((prev) => ({ ...prev, name: getFmPlanName(prev.unitName, kind) ?? prev.name }))
    setNameKindAnchor(null)
  }

  const [formData, setFormData] = useState<PlanFormData>(() => ({
    // 이름이 주어지지 않은 fm:// 진입(폴더에서 계획 추가)은 마지막 형식으로 채운다.
    name: initialData?.name ?? getFmPlanName(initialData?.unitName ?? '', nameKind) ?? '',
    unitName: initialData?.unitName ?? '',
    unitAmount: initialData?.unitAmount ?? 1,
    totalAmount: initialData?.totalAmount ?? 100,
    scheduleType: initialData?.scheduleType ?? 'daily',
    scheduleDays: initialData?.scheduleDays ?? ['mon', 'tue', 'wed', 'thu', 'fri'],
    startDate: initialData?.startDate ?? toLocalDateKey(new Date()),
  }))

  const isFmUnit = parseFmUrl(formData.unitName) !== null
  const nameKindLabel = FM_PLAN_NAME_KINDS.find((k) => k.kind === nameKind)?.label

  const previewPlan = {
    name: formData.name,
    unit_name: formData.unitName,
    unit_amount: formData.unitAmount,
    total_amount: formData.totalAmount,
    schedule_type: formData.scheduleType,
    schedule_days: formData.scheduleType === 'weekly' ? formData.scheduleDays : null,
    start_date: formData.startDate,
  }

  const totalSessions = calculateTotalSessions({
    ...previewPlan,
    id: 0,
    user_id: '',
    created_at: '',
    updated_at: '',
    completed_at: null,
    paused_at: null,
  })
  const endDate = calculateEndDate({
    ...previewPlan,
    id: 0,
    user_id: '',
    created_at: '',
    updated_at: '',
    completed_at: null,
    paused_at: null,
  })

  async function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault()
    await onSubmit(formData)
  }

  function handleScheduleDaysChange(_: React.MouseEvent<HTMLElement>, newDays: WeekDay[]) {
    setFormData((prev) => ({ ...prev, scheduleDays: newDays }))
  }

  return (
    <Box component="form" onSubmit={handleSubmit} sx={{ pb: 2 }}>
      <Typography variant="h5" gutterBottom>
        {title}
      </Typography>

      {error && (
        <Alert severity="error" sx={{ mb: 2 }}>
          {error}
        </Alert>
      )}

      <Stack spacing={3}>
        <TextField
          label="계획 이름"
          value={formData.name}
          onChange={(e) => setFormData((prev) => ({ ...prev, name: e.target.value }))}
          placeholder="예: 알고리즘 문제풀이"
          fullWidth
          required
          slotProps={{
            input: {
              endAdornment: isFmUnit && (
                <InputAdornment position="end">
                  <Button
                    size="small"
                    onClick={(e) => setNameKindAnchor(e.currentTarget)}
                    endIcon={<ArrowDropDownIcon />}
                    aria-label="계획 이름 형식"
                    sx={{ minWidth: 0, px: 0.5, whiteSpace: 'nowrap' }}
                  >
                    {nameKindLabel}
                  </Button>
                </InputAdornment>
              ),
            },
          }}
        />
        <Menu
          anchorEl={nameKindAnchor}
          open={Boolean(nameKindAnchor)}
          onClose={() => setNameKindAnchor(null)}
          anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
          transformOrigin={{ vertical: 'top', horizontal: 'right' }}
        >
          {FM_PLAN_NAME_KINDS.map(({ kind, label }) => (
            <MenuItem
              key={kind}
              selected={kind === nameKind}
              onClick={() => handleNameKindSelect(kind)}
            >
              <ListItemText primary={label} secondary={getFmPlanName(formData.unitName, kind)} />
            </MenuItem>
          ))}
        </Menu>

        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
          <TextField
            label="훈련 단위"
            value={formData.unitName}
            onChange={(e) => setFormData((prev) => withUnitName(prev, e.target.value))}
            placeholder="예: 문제, 페이지, 강의"
            fullWidth
            required
          />
          <IconButton onClick={() => setFmDialogOpen(true)} title="Flash-Man 폴더 선택">
            <FolderOpenIcon />
          </IconButton>
        </Box>

        <NumberSpinner
          style={{ marginTop: '1rem' }}
          label="1회당 훈련량"
          min={1}
          value={formData.unitAmount}
          onValueChange={(value) => {
            if (value) {
              setFormData((prev) => ({ ...prev, unitAmount: value }))
            }
          }}
        />
        <NumberSpinner
          label="전체 훈련량"
          min={1}
          value={formData.totalAmount}
          onValueChange={(value) => {
            if (value) {
              setFormData((prev) => ({ ...prev, totalAmount: value }))
            }
          }}
        />

        <TextField
          label="시작일"
          type="date"
          value={formData.startDate}
          onChange={(e) => setFormData((prev) => ({ ...prev, startDate: e.target.value }))}
          fullWidth
        />

        <FormControl>
          <FormLabel>훈련 주기</FormLabel>
          <RadioGroup
            row
            value={formData.scheduleType}
            onChange={(e) =>
              setFormData((prev) => ({ ...prev, scheduleType: e.target.value as ScheduleType }))
            }
          >
            <FormControlLabel value="daily" control={<Radio />} label="매일" />
            <FormControlLabel value="weekly" control={<Radio />} label="주간 (요일 선택)" />
          </RadioGroup>
        </FormControl>

        {formData.scheduleType === 'weekly' && (
          <Box>
            <FormLabel sx={{ mb: 1, display: 'block' }}>훈련 요일</FormLabel>
            <ToggleButtonGroup
              value={formData.scheduleDays}
              onChange={handleScheduleDaysChange}
              aria-label="훈련 요일"
            >
              {ALL_WEEKDAYS.map((day) => (
                <ToggleButton key={day} value={day}>
                  {getWeekDayLabel(day)}
                </ToggleButton>
              ))}
            </ToggleButtonGroup>
          </Box>
        )}

        <Paper
          sx={{
            p: 2,
            bgcolor: (theme) => (theme.palette.mode === 'dark' ? 'grey.900' : 'grey.50'),
          }}
        >
          <Typography variant="subtitle2" color="text.secondary" gutterBottom>
            예상 훈련 정보
          </Typography>
          <Typography variant="body2">
            총 훈련 횟수: <strong>{totalSessions}회</strong>
          </Typography>
          <Typography variant="body2">
            예상 종료일: <strong>{formatYearDate(endDate)}</strong>
          </Typography>
        </Paper>

        <Stack direction="row" spacing={2}>
          <Button variant="outlined" onClick={onCancel} disabled={loading}>
            취소
          </Button>
          <Button type="submit" variant="contained" disabled={loading}>
            {loading ? loadingLabel : submitLabel}
          </Button>
        </Stack>
      </Stack>

      <FlashManFolderDialog
        open={fmDialogOpen}
        onClose={() => setFmDialogOpen(false)}
        onSelect={handleFmSelect}
      />
    </Box>
  )
}
